-- Rôle de chaque semaine dans le plan (translations_json.weeks, 9 langues). Rejouable.
UPDATE public.training_plans SET translations_json = jsonb_set(coalesce(translations_json, '{}'::jsonb), '{weeks}', '{"1": {"fr": "Prise de repères : des blocs de 5'' à 70 % FTP qui alternent aéro et relevé, du seuil et de la PMA courts avec récupération en aéro. Le but n''est pas encore de tenir longtemps, mais de trouver une position que tu sais reprendre.", "en": "Getting your bearings: 5'' blocks at 70 % FTP alternating aero and upright, plus short threshold and VO2max efforts with recovery in aero. The goal isn''t to hold it for long yet, but to find a position you know how to get back into.", "es": "Toma de referencias: bloques de 5'' al 70 % FTP alternando aero y erguido, umbral y VO2max cortos con recuperación en aero. El objetivo aún no es aguantar mucho tiempo, sino encontrar una posición que sepas recuperar.", "it": "Prendere i riferimenti: blocchi di 5'' al 70 % FTP alternando aero ed eretto, soglia e VO2max brevi con recupero in aero. L''obiettivo non è ancora tenere a lungo, ma trovare una posizione che sai riprendere.", "pt": "Pegar as referências: blocos de 5'' a 70 % FTP alternando aero e ereto, limiar e VO2max curtos com recuperação em aero. O objetivo ainda não é segurar por muito tempo, mas encontrar uma posição que você saiba retomar.", "de": "Orientierung: 5''-Blöcke bei 70 % FTP im Wechsel zwischen Aero und aufrecht, dazu kurze Schwellen- und VO2max-Einheiten mit Erholung in Aero-Position. Es geht noch nicht darum, lange durchzuhalten, sondern eine Position zu finden, die du zuverlässig wieder einnehmen kannst.", "nl": "Oriëntatie: blokken van 5'' op 70 % FTP, afwisselend in aerohouding en rechtop, plus korte drempel- en VO2max-inspanningen met herstel in aerohouding. Het doel is nog niet om lang vol te houden, maar een houding te vinden die je telkens weer kunt aannemen.", "ja": "目安づくり：FTPの70 %で5''のブロックをエアロと起き上がった姿勢で交互に行い、短い閾値とVO2maxはエアロポジションで回復。まだ長く保つことが目的ではなく、確実に戻れるポジションを見つけることが目的です。", "tr": "Referans alma: FTP''nin %70''inde aero ve dik arasında değişen 5''lik bloklar, aero pozisyonda toparlanmalı kısa eşik ve VO2max. Amaç henüz uzun süre tutmak değil, tekrar alabildiğin bir pozisyon bulmak."}, "2": {"fr": "Les blocs aéro doublent (10'') et une sortie longue arrive. Ton cou et ton dos commencent à s''adapter : c''est la semaine où la position devient moins inconfortable, à condition de ne pas forcer la hauteur.", "en": "The aero blocks double (10'') and a long ride comes in. Your neck and back start to adapt: this is the week the position becomes less uncomfortable, as long as you don''t force the height.", "es": "Los bloques aero se duplican (10'') y llega una salida larga. Tu cuello y tu espalda empiezan a adaptarse: es la semana en que la posición se vuelve menos incómoda, siempre que no fuerces la altura.", "it": "I blocchi aero raddoppiano (10'') e arriva un''uscita lunga. Collo e schiena iniziano ad adattarsi: è la settimana in cui la posizione diventa meno scomoda, a patto di non forzare l''altezza.", "pt": "Os blocos aero dobram (10'') e chega um treino longo. Seu pescoço e suas costas começam a se adaptar: é a semana em que a posição fica menos desconfortável, desde que você não force a altura.", "de": "Die Aero-Blöcke verdoppeln sich (10'') und eine lange Fahrt kommt hinzu. Nacken und Rücken beginnen sich anzupassen: In dieser Woche wird die Position weniger unbequem, solange du die Höhe nicht erzwingst.", "nl": "De aeroblokken verdubbelen (10'') en er komt een lange rit bij. Je nek en rug beginnen zich aan te passen: deze week wordt de houding minder oncomfortabel, op voorwaarde dat je de hoogte niet forceert.", "ja": "エアロのブロックは2倍（10''）になり、ロングライドが加わります。首と背中が適応し始め、ポジションの不快感が減ってくる週です。ただし高さを無理に下げないこと。", "tr": "Aero bloklar ikiye katlanıyor (10'') ve uzun sürüş geliyor. Boynun ve sırtın uyum sağlamaya başlıyor: yüksekliği zorlamadığın sürece pozisyonun daha az rahatsız ettiği hafta bu."}, "3": {"fr": "Semaine la plus chargée : blocs aéro de 20'', seuil en 2×15'' et, pour la première fois, la PMA entièrement en aéro. Tu combines intensité et position, c''est ce qui prépare le test de la dernière semaine.", "en": "Heaviest week: 20'' aero blocks, threshold as 2×15'' and, for the first time, VO2max entirely in aero. You combine intensity and position, which is what prepares the test in the final week.", "es": "Semana más cargada: bloques aero de 20'', umbral en 2×15'' y, por primera vez, el VO2max entero en aero. Combinas intensidad y posición, y eso es lo que prepara el test de la última semana.", "it": "Settimana più carica: blocchi aero di 20'', soglia in 2×15'' e, per la prima volta, il VO2max interamente in aero. Unisci intensità e posizione: è ciò che prepara il test dell''ultima settimana.", "pt": "Semana mais carregada: blocos aero de 20'', limiar em 2×15'' e, pela primeira vez, o VO2max inteiro em aero. Você combina intensidade e posição, é isso que prepara o teste da última semana.", "de": "Die härteste Woche: 20''-Aero-Blöcke, Schwelle in 2×15'' und erstmals VO2max komplett in Aero-Position. Du kombinierst Intensität und Position – genau das bereitet den Test der letzten Woche vor.", "nl": "De zwaarste week: aeroblokken van 20'', drempel in 2×15'' en voor het eerst VO2max volledig in aerohouding. Je combineert intensiteit en houding, en dat bereidt de test van de laatste week voor.", "ja": "最も負荷の高い週：20''のエアロブロック、2×15''の閾値、そして初めてVO2maxをすべてエアロで。強度とポジションを組み合わせ、最終週のテストに備えます。", "tr": "En yoğun hafta: 20''lik aero bloklar, 2×15'' eşik ve ilk kez tamamen aero pozisyonda VO2max. Yoğunluğu ve pozisyonu birleştiriyorsun, son haftanın testine hazırlayan da bu."}, "4": {"fr": "Volume réduit pour assimiler : le corps progresse pendant le repos, pas pendant l''effort. La séance clé reste exigeante sur la position : 45'' d''affilée en aéro, pour vérifier que tout ce qui a été construit tient.", "en": "Reduced volume to absorb the work: your body improves during rest, not during effort. The key session stays demanding on position: 45'' straight in aero, to check that everything you''ve built holds.", "es": "Volumen reducido para asimilar: el cuerpo progresa durante el descanso, no durante el esfuerzo. La sesión clave sigue siendo exigente con la posición: 45'' seguidos en aero, para comprobar que todo lo construido se mantiene.", "it": "Volume ridotto per assimilare: il corpo progredisce durante il riposo, non durante lo sforzo. La seduta chiave resta impegnativa sulla posizione: 45'' di fila in aero, per verificare che tutto ciò che hai costruito regga.", "pt": "Volume reduzido para assimilar: o corpo evolui durante o descanso, não durante o esforço. A sessão-chave continua exigente na posição: 45'' seguidos em aero, para verificar se tudo o que foi construído se mantém.", "de": "Weniger Umfang, um zu verarbeiten: Der Körper wird in der Erholung stärker, nicht während der Belastung. Die Schlüsseleinheit bleibt fordernd für die Position: 45'' am Stück in Aero-Position, um zu prüfen, ob alles Aufgebaute hält.", "nl": "Minder volume om te verwerken: het lichaam wordt sterker tijdens het herstel, niet tijdens de inspanning. De sleuteltraining blijft veeleisend voor de houding: 45'' aan één stuk in aerohouding, om te controleren of alles wat is opgebouwd standhoudt.", "ja": "吸収のためにボリュームを減らします。体は努力中ではなく休息中に進歩します。キーセッションはポジション面で厳しいまま：エアロで45''連続、積み上げたものが維持できるか確認します。", "tr": "Özümsemek için hacim azalıyor: vücut eforda değil, dinlenirken gelişir. Ana antrenman pozisyon açısından zorlu kalıyor: aero pozisyonda kesintisiz 45'', inşa edilen her şeyin yerinde durduğunu doğrulamak için."}}'::jsonb) WHERE name_key = 'base_ftp_aero_4w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(coalesce(translations_json, '{}'::jsonb), '{weeks}', '{"1": {"fr": "Adaptation : blocs TT de 15'' en endurance, du tempo court et une première sortie longue. Ces semaines servent à installer la position à basse intensité, là où l''attention peut rester sur la tenue.", "en": "Adaptation: 15'' TT blocks at endurance pace, short tempo and a first long ride. These weeks settle the position at low intensity, where your attention can stay on holding it.", "es": "Adaptación: bloques de 15'' en TT en resistencia, tempo corto y una primera salida larga. Estas semanas sirven para asentar la posición a baja intensidad, donde la atención puede centrarse en mantenerla.", "it": "Adattamento: blocchi in TT di 15'' in endurance, ritmo tempo breve e una prima uscita lunga. Queste settimane servono a fissare la posizione a bassa intensità, dove l''attenzione può restare sulla tenuta.", "pt": "Adaptação: blocos em TT de 15'' em endurance, ritmo tempo curto e um primeiro treino longo. Estas semanas servem para fixar a posição em baixa intensidade, onde a atenção pode ficar na sustentação.", "de": "Anpassung: 15''-TT-Blöcke im Grundlagenbereich, kurzes Tempo und eine erste lange Fahrt. Diese Wochen dienen dazu, die Position bei niedriger Intensität zu festigen, wo die Aufmerksamkeit bei der Haltung bleiben kann.", "nl": "Aanpassing: TT-blokken van 15'' in duurtempo, kort tempo en een eerste lange rit. Deze weken dienen om de houding aan te leren op lage intensiteit, waar je aandacht bij de houding kan blijven.", "ja": "適応：エンデュランスで15''のTTブロック、短いテンポ、最初のロングライド。この期間は低強度でポジションを定着させ、姿勢の維持に意識を向けられるようにします。", "tr": "Uyum: dayanıklılık temposunda 15''lik TT blokları, kısa tempo ve ilk uzun sürüş. Bu haftalar pozisyonu düşük yoğunlukta, dikkatin duruşta kalabildiği yerde oturtmak içindir."}, "2": {"fr": "Les blocs passent à 20'' et une 4e séance s''ajoute. Ton dos et ta nuque encaissent plus de temps en TT ; garde l''intensité basse, c''est la durée qui progresse.", "en": "Blocks go up to 20'' and a 4th session is added. Your back and neck take more time in TT; keep the intensity low, it''s the duration that progresses.", "es": "Los bloques pasan a 20'' y se añade una 4.ª sesión. Tu espalda y tu nuca aguantan más tiempo en TT; mantén la intensidad baja, lo que progresa es la duración.", "it": "I blocchi passano a 20'' e si aggiunge una 4a seduta. Schiena e collo reggono più tempo in TT; tieni bassa l''intensità, è la durata che cresce.", "pt": "Os blocos passam para 20'' e entra uma 4ª sessão. Suas costas e sua nuca aguentam mais tempo em TT; mantenha a intensidade baixa, é a duração que evolui.", "de": "Die Blöcke steigen auf 20'' und eine 4. Einheit kommt hinzu. Rücken und Nacken halten mehr Zeit in TT aus; halte die Intensität niedrig, es ist die Dauer, die wächst.", "nl": "De blokken gaan naar 20'' en er komt een 4e training bij. Je rug en nek verdragen meer tijd in TT; houd de intensiteit laag, het is de duur die toeneemt.", "ja": "ブロックは20''になり、4回目のセッションが加わります。背中と首がTTでより長い時間に耐えます。強度は低く保ち、伸ばすのは時間です。", "tr": "Bloklar 20'' oluyor ve 4. antrenman ekleniyor. Sırtın ve ensen TT''de daha uzun süreye dayanıyor; yoğunluğu düşük tut, gelişen süre."}, "3": {"fr": "Semaine de surcharge : 40'' d''affilée en TT, tempo en 3×12'' et 80'' de sortie longue. C''est la marche la plus haute du plan, celle qui fait progresser la tolérance à la position.", "en": "Overload week: 40'' straight in TT, tempo as 3×12'' and an 80'' long ride. This is the highest step of the plan, the one that builds your tolerance to the position.", "es": "Semana de sobrecarga: 40'' seguidos en TT, tempo en 3×12'' y 80'' de salida larga. Es el escalón más alto del plan, el que hace progresar la tolerancia a la posición.", "it": "Settimana di sovraccarico: 40'' di fila in TT, ritmo tempo in 3×12'' e 80'' di uscita lunga. È il gradino più alto del piano, quello che migliora la tolleranza alla posizione.", "pt": "Semana de sobrecarga: 40'' seguidos em TT, ritmo tempo em 3×12'' e 80'' de treino longo. É o degrau mais alto do plano, o que faz evoluir a tolerância à posição.", "de": "Belastungsspitzeswoche: 40'' am Stück in TT, Tempo in 3×12'' und 80'' lange Fahrt. Das ist die höchste Stufe des Plans, die die Toleranz für die Position verbessert.", "nl": "Piekbelastingsweek: 40'' aan één stuk in TT, tempo in 3×12'' en een lange rit van 80''. Dit is de hoogste trede van het plan, die je tolerantie voor de houding verbetert.", "ja": "オーバーロードの週：TTで40''連続、テンポ3×12''、80''のロングライド。プランで最も高い段階で、ポジションへの耐性を伸ばします。", "tr": "Yüklenme haftası: TT''de kesintisiz 40'', tempo 3×12'' ve 80'' uzun sürüş. Planın en yüksek basamağı, pozisyona toleransı geliştiren bu."}, "4": {"fr": "Une séance en moins et moins d''intensité pour assimiler, mais un bloc de 50'' en TT pour confirmer le gain. Si tu le tiens sans te relever, la base est en place pour un plan plus long.", "en": "One session fewer and less intensity to absorb the work, but a 50'' block in TT to confirm the gain. If you hold it without sitting up, the base is in place for a longer plan.", "es": "Una sesión menos y menos intensidad para asimilar, pero un bloque de 50'' en TT para confirmar la mejora. Si lo aguantas sin erguirte, la base está lista para un plan más largo.", "it": "Una seduta in meno e meno intensità per assimilare, ma un blocco di 50'' in TT per confermare il progresso. Se lo tieni senza alzarti, la base è pronta per un piano più lungo.", "pt": "Uma sessão a menos e menos intensidade para assimilar, mas um bloco de 50'' em TT para confirmar o ganho. Se você segurar sem se levantar, a base está pronta para um plano mais longo.", "de": "Eine Einheit weniger und weniger Intensität zum Verarbeiten, aber ein 50''-Block in TT, um den Fortschritt zu bestätigen. Hältst du ihn, ohne dich aufzurichten, steht die Basis für einen längeren Plan.", "nl": "Eén training minder en minder intensiteit om te verwerken, maar een blok van 50'' in TT om de winst te bevestigen. Houd je dat vol zonder rechtop te komen, dan staat de basis voor een langer plan.", "ja": "吸収のためにセッションを1回減らし強度も下げますが、成果を確かめるためTTで50''のブロックを行います。起き上がらずに保てれば、より長いプランへの土台ができています。", "tr": "Özümsemek için bir antrenman eksik ve daha az yoğunluk, ama kazancı teyit etmek için TT''de 50''lik bir blok. Doğrulmadan tutarsan, daha uzun bir plan için temel hazır."}}'::jsonb) WHERE name_key = 'endurance_tt_4w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(coalesce(translations_json, '{}'::jsonb), '{weeks}', '{"1": {"fr": "Découverte : 8 sprints assis de 15'''' et 6 relances d''1'' en TT. L''objectif est d''apprendre à pousser fort sans lever la tête ni lâcher les prolongateurs, puissance encore contenue.", "en": "Discovery: 8 seated 15'''' sprints and 6 one-minute surges in TT. The goal is to learn to push hard without lifting your head or letting go of the extensions, with power still held back.", "es": "Descubrimiento: 8 sprints sentado de 15'''' y 6 cambios de ritmo de 1'' en TT. El objetivo es aprender a empujar fuerte sin levantar la cabeza ni soltar los acoples, con la potencia aún contenida.", "it": "Scoperta: 8 sprint da seduto di 15'''' e 6 rilanci di 1'' in TT. L''obiettivo è imparare a spingere forte senza alzare la testa né lasciare le protesi, con potenza ancora contenuta.", "pt": "Descoberta: 8 sprints sentado de 15'''' e 6 retomadas de 1'' em TT. O objetivo é aprender a empurrar forte sem levantar a cabeça nem soltar o clipe, com potência ainda contida.", "de": "Kennenlernen: 8 Sitzsprints à 15'''' und 6 Antritte à 1'' in TT. Ziel ist, hart zu treten, ohne den Kopf zu heben oder den Aufsatz loszulassen – die Leistung noch kontrolliert.", "nl": "Kennismaking: 8 zittende sprints van 15'''' en 6 versnellingen van 1'' in TT. Het doel is hard leren trappen zonder je hoofd op te tillen of de opzetstukken los te laten, met nog beheerst vermogen.", "ja": "導入：シッティングで15''''のスプリント8本と、TTで1''の加速6本。頭を上げずエアロバーを離さずに強く踏むことを学びます。パワーはまだ抑えめに。", "tr": "Keşif: oturarak 8 adet 15'''' sprint ve TT''de 6 adet 1'' atak. Amaç başını kaldırmadan ve uzatmaları bırakmadan sert basmayı öğrenmek; güç henüz kontrollü."}, "2": {"fr": "Le volume monte (10 sprints, 8 relances) et les 30/30 apparaissent. La capacité anaérobie se développe ; la difficulté devient de rester en TT quand le souffle est court.", "en": "Volume rises (10 sprints, 8 surges) and 30/30s appear. Anaerobic capacity develops; the challenge becomes staying in TT when you''re short of breath.", "es": "El volumen sube (10 sprints, 8 cambios de ritmo) y aparecen los 30/30. La capacidad anaeróbica se desarrolla; la dificultad pasa a ser mantenerte en TT cuando te falta el aliento.", "it": "Il volume sale (10 sprint, 8 rilanci) e compaiono i 30/30. La capacità anaerobica si sviluppa; la difficoltà diventa restare in TT quando il fiato è corto.", "pt": "O volume sobe (10 sprints, 8 retomadas) e aparecem os 30/30. A capacidade anaeróbia se desenvolve; a dificuldade passa a ser ficar em TT quando o fôlego está curto.", "de": "Der Umfang steigt (10 Sprints, 8 Antritte) und die 30/30 kommen dazu. Die anaerobe Kapazität entwickelt sich; die Schwierigkeit ist nun, in TT zu bleiben, wenn der Atem knapp wird.", "nl": "Het volume stijgt (10 sprints, 8 versnellingen) en de 30/30''s verschijnen. De anaerobe capaciteit ontwikkelt zich; de uitdaging wordt in TT te blijven als je adem tekortschiet.", "ja": "ボリュームが増え（スプリント10本、加速8本）、30/30が登場します。無酸素能力が伸び、息が苦しいときにTTを保つことが課題になります。", "tr": "Hacim artıyor (10 sprint, 8 atak) ve 30/30''lar geliyor. Anaerobik kapasite gelişiyor; zorluk, nefesin kesildiğinde TT''de kalmak oluyor."}, "3": {"fr": "Semaine la plus dure : sprints de 20'''', 3 séries de 30/30 et 10 relances. C''est ici que la puissance maximale en aéro progresse le plus, à condition de garder une récupération complète entre les sprints.", "en": "Hardest week: 20'''' sprints, 3 sets of 30/30 and 10 surges. This is where your maximum power in aero improves most, as long as you recover fully between sprints.", "es": "Semana más dura: sprints de 20'''', 3 series de 30/30 y 10 cambios de ritmo. Aquí es donde más progresa la potencia máxima en aero, siempre que recuperes por completo entre sprints.", "it": "Settimana più dura: sprint di 20'''', 3 serie di 30/30 e 10 rilanci. È qui che la potenza massima in aero cresce di più, a patto di recuperare completamente tra gli sprint.", "pt": "Semana mais dura: sprints de 20'''', 3 séries de 30/30 e 10 retomadas. É aqui que a potência máxima em aero mais evolui, desde que a recuperação entre os sprints seja completa.", "de": "Die härteste Woche: 20''''-Sprints, 3 Serien 30/30 und 10 Antritte. Hier wächst die Maximalleistung in Aero-Position am stärksten, sofern du zwischen den Sprints vollständig erholst.", "nl": "De zwaarste week: sprints van 20'''', 3 series 30/30 en 10 versnellingen. Hier groeit het maximale vermogen in aerohouding het meest, op voorwaarde dat je volledig herstelt tussen de sprints.", "ja": "最もきつい週：20''''のスプリント、30/30を3セット、加速10本。スプリント間で完全に回復することを条件に、エアロでの最大パワーが最も伸びるのはここです。", "tr": "En zor hafta: 20'''' sprintler, 3 set 30/30 ve 10 atak. Sprintler arasında tam toparlanmayı korursan aero''da maksimum gücün en çok geliştiği yer burası."}, "4": {"fr": "On allège pour que la fraîcheur revienne : moins de répétitions, une endurance TT de 40''. Les sprints de cette semaine doivent sortir plus fort qu''en semaine 1, c''est le signe que le travail a pris.", "en": "A lighter week so freshness comes back: fewer reps, a 40'' TT endurance ride. This week''s sprints should come out stronger than in week 1, the sign that the work has paid off.", "es": "Aligeramos para recuperar la frescura: menos repeticiones, una resistencia en TT de 40''. Los sprints de esta semana deben salir más fuertes que en la semana 1, señal de que el trabajo ha surtido efecto.", "it": "Si alleggerisce per ritrovare la freschezza: meno ripetute, un endurance in TT di 40''. Gli sprint di questa settimana devono uscire più forti che in settimana 1: è il segno che il lavoro ha fatto effetto.", "pt": "Aliviamos para a disposição voltar: menos repetições, um endurance em TT de 40''. Os sprints desta semana devem sair mais fortes que na semana 1, é o sinal de que o trabalho deu resultado.", "de": "Wir entlasten, damit die Frische zurückkommt: weniger Wiederholungen, 40'' TT-Grundlage. Die Sprints dieser Woche sollten stärker ausfallen als in Woche 1 – das Zeichen, dass das Training gewirkt hat.", "nl": "We bouwen af zodat de frisheid terugkomt: minder herhalingen, 40'' duur in TT. De sprints van deze week moeten krachtiger zijn dan in week 1: het teken dat de training is aangeslagen.", "ja": "フレッシュさを取り戻すために軽くします：反復を減らし、TTでのエンデュランス40''。今週のスプリントは1週目より強く出るはずで、それがトレーニングの効果の証です。", "tr": "Tazeliğin geri gelmesi için hafifletiyoruz: daha az tekrar, 40'' TT dayanıklılık. Bu haftanın sprintleri 1. haftadakinden daha güçlü çıkmalı, çalışmanın tuttuğunun işareti bu."}}'::jsonb) WHERE name_key = 'sprint_tt_4w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(coalesce(translations_json, '{}'::jsonb), '{weeks}', '{"1": {"fr": "Mise en route au seuil : sweet spot 3×10'', seuil 4×6'' et efforts de 3'' à la puissance critique, tous en TT. On mesure ce que tu peux produire couché avant d''allonger les blocs.", "en": "Easing into threshold: sweet spot 3×10'', threshold 4×6'' and 3'' efforts at critical power, all in TT. We measure what you can produce tucked low before lengthening the blocks.", "es": "Puesta en marcha en el umbral: sweet spot 3×10'', umbral 4×6'' y esfuerzos de 3'' a potencia crítica, todo en TT. Medimos lo que puedes producir acoplado antes de alargar los bloques.", "it": "Avvio alla soglia: sweet spot 3×10'', soglia 4×6'' e sforzi di 3'' alla potenza critica, tutti in TT. Misuriamo ciò che sai produrre in posizione aero prima di allungare i blocchi.", "pt": "Início no limiar: sweet spot 3×10'', limiar 4×6'' e esforços de 3'' na potência crítica, todos em TT. Medimos o que você consegue produzir em posição aero antes de alongar os blocos.", "de": "Einstieg an der Schwelle: Sweet Spot 3×10'', Schwelle 4×6'' und 3''-Belastungen bei kritischer Leistung, alles in TT. Wir messen, was du liegend leisten kannst, bevor die Blöcke länger werden.", "nl": "Instap op de drempel: sweet spot 3×10'', drempel 4×6'' en inspanningen van 3'' op kritisch vermogen, allemaal in TT. We meten wat je liggend kunt leveren voordat de blokken langer worden.", "ja": "閾値への導入：スイートスポット3×10''、閾値4×6''、クリティカルパワーで3''の努力、すべてTTで。ブロックを伸ばす前に、伏せた姿勢で出せるパワーを測ります。", "tr": "Eşiğe giriş: sweet spot 3×10'', eşik 4×6'' ve kritik güçte 3'' eforlar, hepsi TT''de. Blokları uzatmadan önce yatık pozisyonda ne üretebildiğini ölçüyoruz."}, "2": {"fr": "Les blocs s''allongent (12'', 8'') et les sur-sous arrivent : alterner 108 et 95 % FTP en TT apprend à garder la position quand l''intensité varie, comme en course.", "en": "Blocks get longer (12'', 8'') and over-unders arrive: alternating 108 and 95 % FTP in TT teaches you to keep the position when the intensity varies, like in a race.", "es": "Los bloques se alargan (12'', 8'') y llegan los sobre-bajo: alternar 108 y 95 % FTP en TT te enseña a mantener la posición cuando la intensidad varía, como en carrera.", "it": "I blocchi si allungano (12'', 8'') e arrivano i sopra-sotto: alternare 108 e 95 % FTP in TT insegna a mantenere la posizione quando l''intensità varia, come in gara.", "pt": "Os blocos se alongam (12'', 8'') e chegam os acima-abaixo: alternar 108 e 95 % FTP em TT ensina a manter a posição quando a intensidade varia, como em prova.", "de": "Die Blöcke werden länger (12'', 8'') und die Over-Under kommen: Der Wechsel zwischen 108 und 95 % FTP in TT lehrt dich, die Position zu halten, wenn die Intensität schwankt – wie im Rennen.", "nl": "De blokken worden langer (12'', 8'') en de over-unders komen erbij: wisselen tussen 108 en 95 % FTP in TT leert je de houding vast te houden als de intensiteit varieert, zoals in een wedstrijd.", "ja": "ブロックが伸び（12''、8''）、オーバーアンダーが登場：TTでFTPの108 %と95 %を交互に行い、レースのように強度が変わってもポジションを保つことを学びます。", "tr": "Bloklar uzuyor (12'', 8'') ve üst-altlar geliyor: TT''de FTP''nin %108 ve %95''ini değiştirmek, yarıştaki gibi yoğunluk değişirken pozisyonu korumayı öğretir."}, "3": {"fr": "Surcharge : 2×20'' en sweet spot, 3×12'' au seuil, 5×4'' à la puissance critique. C''est la semaine qui fait monter la FTP en aéro ; la fatigue est normale, la position doit rester la même jusqu''au bout.", "en": "Overload: 2×20'' sweet spot, 3×12'' threshold, 5×4'' at critical power. This is the week that raises your FTP in aero; fatigue is normal, the position must stay the same to the end.", "es": "Sobrecarga: 2×20'' en sweet spot, 3×12'' en umbral, 5×4'' a potencia crítica. Es la semana que hace subir la FTP en aero; la fatiga es normal, la posición debe mantenerse igual hasta el final.", "it": "Sovraccarico: 2×20'' in sweet spot, 3×12'' alla soglia, 5×4'' alla potenza critica. È la settimana che fa salire la FTP in aero; la fatica è normale, la posizione deve restare la stessa fino alla fine.", "pt": "Sobrecarga: 2×20'' em sweet spot, 3×12'' no limiar, 5×4'' na potência crítica. É a semana que faz subir a FTP em aero; o cansaço é normal, a posição deve continuar a mesma até o fim.", "de": "Belastungsspitze: 2×20'' Sweet Spot, 3×12'' an der Schwelle, 5×4'' bei kritischer Leistung. Diese Woche hebt die FTP in Aero-Position; Müdigkeit ist normal, die Position muss bis zum Ende gleich bleiben.", "nl": "Piekbelasting: 2×20'' sweet spot, 3×12'' op drempel, 5×4'' op kritisch vermogen. Deze week tilt je FTP in aerohouding omhoog; vermoeidheid is normaal, de houding moet tot het einde dezelfde blijven.", "ja": "オーバーロード：スイートスポット2×20''、閾値3×12''、クリティカルパワー5×4''。エアロでのFTPを上げる週です。疲労は普通のこと、ポジションは最後まで同じに保ちます。", "tr": "Yüklenme: sweet spot''ta 2×20'', eşikte 3×12'', kritik güçte 5×4''. Aero''da FTP''yi yükselten hafta bu; yorgunluk normal, pozisyon sonuna kadar aynı kalmalı."}, "4": {"fr": "Volume réduit de près de moitié pour assimiler. Les efforts restent au seuil mais plus courts : tu dois sentir que les mêmes watts en TT demandent moins qu''en semaine 1.", "en": "Volume cut by almost half to absorb the work. Efforts stay at threshold but shorter: you should feel that the same watts in TT cost less than in week 1.", "es": "Volumen reducido casi a la mitad para asimilar. Los esfuerzos siguen en el umbral pero más cortos: debes notar que los mismos vatios en TT te cuestan menos que en la semana 1.", "it": "Volume ridotto quasi della metà per assimilare. Gli sforzi restano alla soglia ma più brevi: devi sentire che gli stessi watt in TT costano meno che in settimana 1.", "pt": "Volume reduzido quase pela metade para assimilar. Os esforços continuam no limiar, mas mais curtos: você deve sentir que os mesmos watts em TT exigem menos que na semana 1.", "de": "Umfang fast halbiert zum Verarbeiten. Die Belastungen bleiben an der Schwelle, aber kürzer: Du solltest spüren, dass dieselben Watt in TT weniger kosten als in Woche 1.", "nl": "Volume bijna gehalveerd om te verwerken. De inspanningen blijven op drempel maar zijn korter: je moet voelen dat dezelfde watts in TT minder kosten dan in week 1.", "ja": "吸収のためにボリュームをほぼ半分に。努力は閾値のままですが短くなります：TTで同じワットが1週目より楽に感じられるはずです。", "tr": "Özümsemek için hacim neredeyse yarıya iniyor. Eforlar eşikte kalıyor ama daha kısa: TT''de aynı wattların 1. haftadan daha az zorladığını hissetmelisin."}}'::jsonb) WHERE name_key = 'threshold_tt_4w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(coalesce(translations_json, '{}'::jsonb), '{weeks}', '{"1": {"fr": "Introduction de la PMA : 4×4'' et 30/15 en position libre, mais chaque récupération et le bloc final se font en TT. Le cerveau apprend à associer la position à la récupération, même essoufflé.", "en": "Introducing VO2max: 4×4'' and 30/15 in free position, but every recovery and the final block are done in TT. Your brain learns to link the position with recovery, even when out of breath.", "es": "Introducción al VO2max: 4×4'' y 30/15 en posición libre, pero cada recuperación y el bloque final se hacen en TT. El cerebro aprende a asociar la posición con la recuperación, incluso sin aliento.", "it": "Introduzione del VO2max: 4×4'' e 30/15 in posizione libera, ma ogni recupero e il blocco finale si fanno in TT. Il cervello impara ad associare la posizione al recupero, anche col fiato corto.", "pt": "Introdução do VO2max: 4×4'' e 30/15 em posição livre, mas cada recuperação e o bloco final são feitos em TT. O cérebro aprende a associar a posição à recuperação, mesmo sem fôlego.", "de": "Einführung VO2max: 4×4'' und 30/15 in freier Position, aber jede Erholung und der Schlussblock in TT. Das Gehirn lernt, die Position mit Erholung zu verbinden, auch außer Atem.", "nl": "Introductie VO2max: 4×4'' en 30/15 in vrije houding, maar elk herstel en het slotblok in TT. Je brein leert de houding te koppelen aan herstel, zelfs buiten adem.", "ja": "VO2maxの導入：4×4''と30/15をフリーポジションで、ただし各回復と最後のブロックはTTで行います。息が上がっていても、脳がポジションと回復を結びつけることを学びます。", "tr": "VO2max''a giriş: serbest pozisyonda 4×4'' ve 30/15, ama her toparlanma ve son blok TT''de. Beyin, nefes nefese olsa bile pozisyonu toparlanmayla ilişkilendirmeyi öğrenir."}, "2": {"fr": "Une répétition de plus sur chaque séance et une sortie longue en TT. La VO2max progresse ; reprendre la position en moins de 5 s après chaque effort devient un réflexe.", "en": "One more rep in each session and a long ride in TT. VO2max improves; getting back into position within 5 s after each effort becomes a reflex.", "es": "Una repetición más en cada sesión y una salida larga en TT. El VO2max progresa; recuperar la posición en menos de 5 s tras cada esfuerzo se convierte en un reflejo.", "it": "Una ripetuta in più in ogni seduta e un''uscita lunga in TT. Il VO2max cresce; riprendere la posizione in meno di 5 s dopo ogni sforzo diventa un riflesso.", "pt": "Uma repetição a mais em cada sessão e um treino longo em TT. O VO2max evolui; retomar a posição em menos de 5 s após cada esforço vira um reflexo.", "de": "Eine Wiederholung mehr pro Einheit und eine lange Fahrt in TT. Die VO2max steigt; die Position nach jeder Belastung in unter 5 s wieder einzunehmen, wird zum Reflex.", "nl": "Eén herhaling meer per training en een lange rit in TT. De VO2max stijgt; binnen 5 s na elke inspanning de houding hervatten wordt een reflex.", "ja": "各セッションで1本増え、TTでのロングライドが加わります。VO2maxが伸び、各努力の後5 s以内にポジションに戻ることが反射になります。", "tr": "Her antrenmanda bir tekrar fazla ve TT''de bir uzun sürüş. VO2max gelişiyor; her eforun ardından 5 s içinde pozisyona dönmek bir refleks haline geliyor."}, "3": {"fr": "Semaine la plus chargée : 6×4'', 30/15 en 3 séries et un 5×5'' supplémentaire. C''est là que la PMA monte le plus ; ta position de récupération doit tenir même quand tout brûle.", "en": "Heaviest week: 6×4'', 30/15 in 3 sets and an extra 5×5''. This is where VO2max rises most; your recovery position must hold even when everything burns.", "es": "Semana más cargada: 6×4'', 30/15 en 3 series y un 5×5'' adicional. Aquí es donde más sube el VO2max; tu posición de recuperación debe aguantar incluso cuando todo quema.", "it": "Settimana più carica: 6×4'', 30/15 in 3 serie e un 5×5'' in più. È qui che il VO2max sale di più; la tua posizione di recupero deve reggere anche quando tutto brucia.", "pt": "Semana mais carregada: 6×4'', 30/15 em 3 séries e um 5×5'' extra. É aí que o VO2max mais sobe; sua posição de recuperação deve se manter mesmo quando tudo queima.", "de": "Die härteste Woche: 6×4'', 30/15 in 3 Serien und zusätzlich 5×5''. Hier steigt die VO2max am stärksten; deine Erholungsposition muss halten, auch wenn alles brennt.", "nl": "De zwaarste week: 6×4'', 30/15 in 3 series en een extra 5×5''. Hier stijgt de VO2max het meest; je herstelhouding moet standhouden, ook als alles brandt.", "ja": "最も負荷の高い週：6×4''、30/15を3セット、さらに5×5''。VO2maxが最も上がるのはここです。すべてが燃えるようでも回復時のポジションを保ちます。", "tr": "En yoğun hafta: 6×4'', 3 set 30/15 ve ek bir 5×5''. VO2max''ın en çok yükseldiği yer burası; her yer yanarken bile toparlanma pozisyonun tutmalı."}, "4": {"fr": "Retour au volume de la semaine 1 pour assimiler. Les mêmes séances doivent paraître plus faciles : c''est le meilleur indicateur que la VO2max a progressé.", "en": "Back to week 1 volume to absorb the work. The same sessions should feel easier: that''s the best sign your VO2max has improved.", "es": "Vuelta al volumen de la semana 1 para asimilar. Las mismas sesiones deben parecer más fáciles: es el mejor indicador de que el VO2max ha progresado.", "it": "Ritorno al volume della settimana 1 per assimilare. Le stesse sedute devono sembrare più facili: è il miglior indicatore che il VO2max è migliorato.", "pt": "Volta ao volume da semana 1 para assimilar. As mesmas sessões devem parecer mais fáceis: é o melhor indicador de que o VO2max evoluiu.", "de": "Zurück zum Umfang von Woche 1 zum Verarbeiten. Dieselben Einheiten sollten leichter wirken: der beste Hinweis, dass die VO2max gestiegen ist.", "nl": "Terug naar het volume van week 1 om te verwerken. Dezelfde trainingen moeten makkelijker aanvoelen: de beste aanwijzing dat je VO2max is gestegen.", "ja": "吸収のため1週目のボリュームに戻します。同じセッションが楽に感じられるはずで、それがVO2maxが伸びた最良の指標です。", "tr": "Özümsemek için 1. haftanın hacmine dönüş. Aynı antrenmanlar daha kolay gelmeli: VO2max''ın geliştiğinin en iyi göstergesi bu."}}'::jsonb) WHERE name_key = 'vo2_tt_4w_name';
